

# This file was *autogenerated* from the file 09_torus_markers.sage
from sage.all_cmdline import *   # import sage library

_sage_const_1p80 = RealNumber('1.80'); _sage_const_0p70 = RealNumber('0.70'); _sage_const_60p0 = RealNumber('60.0'); _sage_const_2 = Integer(2); _sage_const_4 = Integer(4); _sage_const_3 = Integer(3); _sage_const_5 = Integer(5); _sage_const_7 = Integer(7); _sage_const_0 = Integer(0)# Precise projection of half-lattice marker points onto the visible torus
# surface, using the SAME convention as 08_torus_render.sage and
# 10_sphere_render.sage:
#
#   parameterization X(u,v) = ((R + r cos u) cos v, (R + r cos u) sin v, r sin u)
#   projection x_2d = X,  y_2d = Y sin theta + Z cos theta
#   visibility N . (0, -cos theta, sin theta) > 0
#               <=> -cos u sin v cos theta + sin u sin theta > 0
#
# The four half-lattice points (2-torsion of the torus) are embedded at four
# 3D positions on the donut chosen so that all four pass the visibility
# check at theta = 60 deg.  We pick the top crest (u = pi/2, "highest"
# small-circle latitude) at four evenly spaced longitudes v in (0, pi),
# plus one alternative position on the outer equator for the origin.

import math

R = _sage_const_1p80 
r = _sage_const_0p70 
theta = math.radians(_sage_const_60p0 )
st, ct = math.sin(theta), math.cos(theta)

def project(u, v):
    X = (R + r*math.cos(u)) * math.cos(v)
    Y = (R + r*math.cos(u)) * math.sin(v)
    Z = r * math.sin(u)
    x2 = X
    y2 = Y*st + Z*ct
    Ncam = -math.cos(u)*math.sin(v)*ct + math.sin(u)*st
    return X, Y, Z, x2, y2, Ncam

# Markers - all on the top crest (u = pi/2) at four longitudes spaced 90 deg
# apart, so all four are automatically visible (the top crest has normal
# (0,0,1) which has positive dot product with the camera direction).
markers = [
    ("zero",     math.pi/_sage_const_2 ,   math.pi/_sage_const_4 ),     # u=pi/2, v=pi/4   (back-right)
    ("halftwo",  math.pi/_sage_const_2 , _sage_const_3 *math.pi/_sage_const_4 ),     # u=pi/2, v=3pi/4  (back-left)
    ("halfone",  math.pi/_sage_const_2 , _sage_const_5 *math.pi/_sage_const_4 ),     # u=pi/2, v=5pi/4  (front-left)
    ("halfsum",  math.pi/_sage_const_2 , _sage_const_7 *math.pi/_sage_const_4 ),     # u=pi/2, v=7pi/4  (front-right)
]

print("Marker positions (theta = 60 deg):")
print("{:<10} {:>8} {:>8} | {:>8} {:>8} {:>8} | {:>8} {:>8} | {}".format(
    "name","u(deg)","v(deg)","X","Y","Z","x2D","y2D","visible"))
for name, u, v in markers:
    X, Y, Z, x2, y2, Ncam = project(u, v)
    print("{:<10} {:>8.1f} {:>8.1f} | {:>8.3f} {:>8.3f} {:>8.3f} | {:>8.4f} {:>8.4f} | {}".format(
        name, math.degrees(u), math.degrees(v), X, Y, Z, x2, y2,
        "YES" if Ncam > _sage_const_0  else "NO"))

# Embedding figure markers
z_pt = (math.pi/_sage_const_3 , math.pi/_sage_const_3 )
Xz, Yz, Zz, x2z, y2z, Nz = project(*z_pt)
zero_pt = (math.pi/_sage_const_2 , math.pi/_sage_const_2 )
X0, Y0, Z0, x20, y20, N0 = project(*zero_pt)

print()
print("Generic [z]: u=60 deg, v=60 deg -> ({:.4f}, {:.4f}), visible={}".format(
    x2z, y2z, "YES" if Nz > _sage_const_0  else "NO"))
print("Origin [0]:  u=90 deg, v=90 deg -> ({:.4f}, {:.4f}), visible={}".format(
    x20, y20, "YES" if N0 > _sage_const_0  else "NO"))

with open("coords_torus_markers.tex", "w") as f:
    f.write("% Visible-surface markers (theta = 60 deg)\n")
    for name, u, v in markers:
        _, _, _, x2, y2, _ = project(u, v)
        f.write(r"\newcommand{\torusMark%sx}{%.4f}" % (name, x2) + "\n")
        f.write(r"\newcommand{\torusMark%sy}{%.4f}" % (name, y2) + "\n")
    f.write(r"\newcommand{\torusMarkZx}{%.4f}" % x2z + "\n")
    f.write(r"\newcommand{\torusMarkZy}{%.4f}" % y2z + "\n")
    f.write(r"\newcommand{\torusMarkOriginx}{%.4f}" % x20 + "\n")
    f.write(r"\newcommand{\torusMarkOriginy}{%.4f}" % y20 + "\n")
print()
print("Wrote coords_torus_markers.tex")

